fn cdiv_u(a: i32, b: i32) -> u32 {
    (a.wrapping_add(b - 1) / b) as u32
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn gated_delta_rule_recurrence(
    q: *const f32, k: *const f32, v: *const f32, g: *const f32, beta: *const f32, state: *mut f32, output: *mut f32, bh: i32,
    seq_len: i32, k_dim: i32, v_dim: i32, stream: i64,
) {
    let s = cu_stream(stream);
    let (mut q, mut k, mut v, mut g, mut beta, mut state, mut output, mut seq_len, mut k_dim, mut v_dim) =
        (q, k, v, g, beta, state, output, seq_len, k_dim, v_dim);
    let grid = (cdiv_u(v_dim, 64), bh as u32, 1);
    unsafe {
        if k_dim == 128 || k_dim == 64 {
            let name = if k_dim == 128 { GDR_TILED_128 } else { GDR_TILED_64 };
            launch(name, grid, (64, 1, 1), 0, s, &mut args!(q, k, v, g, beta, state, output, seq_len, v_dim));
        } else {
            let smem = (2 * k_dim as i64 * 4) as u32;
            launch(GDR_FALLBACK, grid, (64, 1, 1), smem, s, &mut args!(q, k, v, g, beta, state, output, seq_len, k_dim, v_dim));
        }
    }
}

