/// Block size: the smallest power of two >= head_dim, from 32 up to 1024.
fn ap_block(head_dim: i32) -> u32 {
    let mut b = 32;
    while b < head_dim && b < 1024 {
        b <<= 1;
    }
    b as u32
}

fn ap_name(kind: usize, dtype: i32, neox: bool) -> Option<&'static str> {
    const N: [[[&str; 2]; 3]; 3] = [
        [
            ["_Z23qk_rms_norm_rope_kernelI6__halfLb0EEvPKT_S3_S3_S3_S3_S3_PS1_S4_lllllllliiiiiiiff", "_Z23qk_rms_norm_rope_kernelI6__halfLb1EEvPKT_S3_S3_S3_S3_S3_PS1_S4_lllllllliiiiiiiff"],
            ["_Z23qk_rms_norm_rope_kernelI13__nv_bfloat16Lb0EEvPKT_S3_S3_S3_S3_S3_PS1_S4_lllllllliiiiiiiff", "_Z23qk_rms_norm_rope_kernelI13__nv_bfloat16Lb1EEvPKT_S3_S3_S3_S3_S3_PS1_S4_lllllllliiiiiiiff"],
            ["_Z23qk_rms_norm_rope_kernelIfLb0EEvPKT_S2_S2_S2_S2_S2_PS0_S3_lllllllliiiiiiiff", "_Z23qk_rms_norm_rope_kernelIfLb1EEvPKT_S2_S2_S2_S2_S2_PS0_S3_lllllllliiiiiiiff"],
        ],
        [
            ["_Z33qk_rms_norm_rope_positions_kernelI6__halfLb0EEvPKT_S3_S3_S3_S3_S3_PKjPS1_S6_lllllllliiiiiiff", "_Z33qk_rms_norm_rope_positions_kernelI6__halfLb1EEvPKT_S3_S3_S3_S3_S3_PKjPS1_S6_lllllllliiiiiiff"],
            ["_Z33qk_rms_norm_rope_positions_kernelI13__nv_bfloat16Lb0EEvPKT_S3_S3_S3_S3_S3_PKjPS1_S6_lllllllliiiiiiff", "_Z33qk_rms_norm_rope_positions_kernelI13__nv_bfloat16Lb1EEvPKT_S3_S3_S3_S3_S3_PKjPS1_S6_lllllllliiiiiiff"],
            ["_Z33qk_rms_norm_rope_positions_kernelIfLb0EEvPKT_S2_S2_S2_S2_S2_PKjPS0_S5_lllllllliiiiiiff", "_Z33qk_rms_norm_rope_positions_kernelIfLb1EEvPKT_S2_S2_S2_S2_S2_PKjPS0_S5_lllllllliiiiiiff"],
        ],
        [
            ["_Z34qkv_rms_norm_rope_positions_kernelI6__halfLb0EEvPKT_S3_S3_S3_S3_S3_S3_S3_PKjPS1_S6_S6_lllllllllllliiiiiifff", "_Z34qkv_rms_norm_rope_positions_kernelI6__halfLb1EEvPKT_S3_S3_S3_S3_S3_S3_S3_PKjPS1_S6_S6_lllllllllllliiiiiifff"],
            ["_Z34qkv_rms_norm_rope_positions_kernelI13__nv_bfloat16Lb0EEvPKT_S3_S3_S3_S3_S3_S3_S3_PKjPS1_S6_S6_lllllllllllliiiiiifff", "_Z34qkv_rms_norm_rope_positions_kernelI13__nv_bfloat16Lb1EEvPKT_S3_S3_S3_S3_S3_S3_S3_PKjPS1_S6_S6_lllllllllllliiiiiifff"],
            ["_Z34qkv_rms_norm_rope_positions_kernelIfLb0EEvPKT_S2_S2_S2_S2_S2_S2_S2_PKjPS0_S5_S5_lllllllllllliiiiiifff", "_Z34qkv_rms_norm_rope_positions_kernelIfLb1EEvPKT_S2_S2_S2_S2_S2_S2_S2_PKjPS0_S5_S5_lllllllllllliiiiiifff"],
        ],
    ];
    if !(0..=2).contains(&dtype) {
        return None;
    }
    Some(N[kind][dtype as usize][neox as usize])
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn qk_rms_norm_rope(
    q: *const c_void, k: *const c_void, q_weight: *const c_void, k_weight: *const c_void, cos: *const c_void, sin: *const c_void,
    q_out: *mut c_void, k_out: *mut c_void, q_stride_b: i64, q_stride_h: i64, q_stride_s: i64, q_stride_d: i64, k_stride_b: i64,
    k_stride_h: i64, k_stride_s: i64, k_stride_d: i64, batch: i32, q_heads: i32, k_heads: i32, seq_len: i32, head_dim: i32,
    rot_dim: i32, cos_batch_stride: i32, q_eps: f32, k_eps: f32, is_neox: i32, dtype: i32, stream: i64,
) {
    let Some(name) = ap_name(0, dtype, is_neox != 0) else { return };
    if batch <= 0 || q_heads <= 0 || seq_len <= 0 || head_dim <= 0 || rot_dim <= 0 {
        return;
    }
    let total = batch.wrapping_mul(q_heads.wrapping_add(k_heads)).wrapping_mul(seq_len);
    if total <= 0 {
        return;
    }
    let s = cu_stream(stream);
    let (mut q, mut k, mut qw, mut kw, mut c, mut sn, mut qo, mut ko) = (q, k, q_weight, k_weight, cos, sin, q_out, k_out);
    let (mut a0, mut a1, mut a2, mut a3, mut b0, mut b1, mut b2, mut b3) = (q_stride_b, q_stride_h, q_stride_s, q_stride_d, k_stride_b, k_stride_h, k_stride_s, k_stride_d);
    let (mut ba, mut qh, mut kh, mut sl, mut hd, mut rd, mut cbs, mut qe, mut ke) = (batch, q_heads, k_heads, seq_len, head_dim, rot_dim, cos_batch_stride, q_eps, k_eps);
    unsafe {
        launch(name, (total as u32, 1, 1), (ap_block(head_dim), 1, 1), 0, s,
               &mut args!(q, k, qw, kw, c, sn, qo, ko, a0, a1, a2, a3, b0, b1, b2, b3, ba, qh, kh, sl, hd, rd, cbs, qe, ke))
    };
}

