/// Mangled template-argument spelling of a dtype: 0 f32, 1 f16, 2 bf16.
fn tspell(t: usize) -> &'static str {
    ["f", "6__half", "13__nv_bfloat16"][t]
}

fn vec8_aligned(p: *const c_void) -> bool {
    (p as usize) % 16 == 0
}

unsafe fn rms_residual(t: usize, x: *const c_void, residual: *const c_void, weight: *const c_void, scale: *const c_void, dst: *mut c_void, nrows: i32, ncols: i32, eps: f32, stream: i64) {
    if nrows <= 0 || ncols <= 0 {
        return;
    }
    let s = cu_stream(stream);
    let (mut x, mut r, mut w, mut sc, mut d, mut nc, mut e) = (x, residual, weight, scale, dst, ncols, eps);
    let tail = if t == 0 { "EvPKT_S2_S2_S2_PS0_if" } else { "EvPKT_S3_S3_S3_PS1_if" };
    unsafe {
        if t != 0 && ncols % 8 == 0 && vec8_aligned(x) && vec8_aligned(r) && vec8_aligned(w) && vec8_aligned(d) {
            let vc = ncols / 8;
            let block = ((vc + 31) / 32 * 32).clamp(32, 1024);
            let name = intern(format!("_Z29rms_norm_residual_vec8_kernelI{}{}", tspell(t), tail));
            launch(name, (nrows as u32, 1, 1), (block as u32, 1, 1), 0, s, &mut args!(x, r, w, sc, d, nc, e));
            return;
        }
        let block = if ncols < 1024 { 32 } else { 1024 };
        let name = intern(format!("_Z24rms_norm_residual_kernelI{}{}", tspell(t), tail));
        launch(name, (nrows as u32, 1, 1), (block, 1, 1), 0, s, &mut args!(x, r, w, sc, d, nc, e));
    }
}

