unsafe fn router(
    t: usize, logits: *const c_void, weights: *mut c_void, ids: *mut c_void, selection_bias: *const c_void, expert_scale: *const c_void,
    n_rows: i32, n_experts: i32, top_k: i32, score_mode: i32, weight_mode: i32, renormalize: bool, clamp_logits: bool, clamp_min: f32,
    clamp_max: f32, norm_min: f32, output_scale: f32, stream: i64,
) {
    if ![1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 576].contains(&n_experts) {
        return;
    }
    let s = cu_stream(stream);
    let hb = !selection_bias.is_null();
    let hs = !expert_scale.is_null();
    let tail = if t == 0 { "EEvPKT_PfPjPKfS6_iiiibbffff" } else { "EEvPKT_PfPjPKfS7_iiiibbffff" };
    let name = intern(format!("_Z22moe_router_topk_kernelI{}Li{}ELb{}ELb{}{}", tspell(t), n_experts, hb as u8, hs as u8, tail));
    let (mut l, mut w, mut id, mut b, mut es) = (logits, weights, ids, selection_bias, expert_scale);
    let (mut nr, mut tk, mut sm, mut wm, mut rn, mut cl) = (n_rows, top_k, score_mode, weight_mode, renormalize as u8, clamp_logits as u8);
    let (mut cmin, mut cmax, mut nmin, mut os) = (clamp_min, clamp_max, norm_min, output_scale);
    unsafe {
        launch(name, (((n_rows + 3) / 4) as u32, 1, 1), (32, 4, 1), 0, s,
               &mut args!(l, w, id, b, es, nr, tk, sm, wm, rn, cl, cmin, cmax, nmin, os))
    };
}
